template<class T>std::vector<T>read(const std::string&p,size_t count=0){std::ifstream f(p,std::ios::binary|std::ios::ate);if(!f)exit(2);if(!count)count=f.tellg()/sizeof(T);f.seekg(0);std::vector<T>x(count);f.read((char*)x.data(),count*sizeof(T));if(size_t(f.gcount())!=count*sizeof(T))exit(3);return x;}
struct Field{std::string name;int n;bool integer;std::vector<unsigned>initial;void*base,*ptr;Field(const char*label,int size,bool isint,const char*file):name(label),n(size),integer(isint),initial(size+32,0){unsigned guard=1234567;if(!integer){float v=-2047.5;memcpy(&guard,&v,4);}for(int i=0;i<16;i++)initial[i]=initial[n+16+i]=guard;if(file[0]){auto a=read<unsigned>(file,n);memcpy(initial.data()+16,a.data(),n*4);}C(cudaMalloc(&base,(n+32)*4));ptr=(char*)base+64;reset();}void reset(){C(cudaMemcpy(base,initial.data(),initial.size()*4,cudaMemcpyHostToDevice));}void set(const std::vector<unsigned>&h){C(cudaMemcpy(ptr,h.data(),n*4,cudaMemcpyHostToDevice));}void append(std::vector<float>&out){std::vector<unsigned>h(n+32);C(cudaMemcpy(h.data(),base,h.size()*4,cudaMemcpyDeviceToHost));for(unsigned word:h){if(integer){int v;memcpy(&v,&word,4);out.push_back(float(v));}else{float v;memcpy(&v,&word,4);out.push_back(v);}}}~Field(){cudaFree(base);}};
